/**
 * The three loads `prog()` writes itself, in all four languages.
 *
 * These are not numbers — they are sentences about the number: "whatever you lifted
 * in block 1, plus some", "heavy", "back to the block 2 load". They appeared in the
 * Carga column of every screen in Portuguese whatever language the app was in, which
 * is the day-name bug one column to the right. Named here rather than written inline
 * so there is one place to read what block 2 actually asks of you.
 */
const B2_LOAD: Localized = {
  pt: 'base + carga',
  en: 'base + load',
  es: 'base + carga',
  fr: 'base + charge',
};

const B3_LOAD: Localized = { pt: 'pesada', en: 'heavy', es: 'pesada', fr: 'lourde' };

const DL_LOAD: Localized = { pt: 'carga B2', en: 'B2 load', es: 'carga B2', fr: 'charge B2' };

export function prog(
  sets: number,
  loadB1: Localized,
  rest: string,
  kind: ProgKind,
): SlotPrescriptions {
  const R = RANGES[kind];
  const s3 = kind === 'comp' ? sets + 1 : sets;
  const at = (k: 'b1' | 'b2' | 'b3' | 'dl', s: number, l: Localized): Prescription => ({
    s,
    r: R[k][0],
    rpe: R[k][1],
    l,
    rest,
  });
  return {
    b1: at('b1', sets, loadB1),
    b2: at('b2', sets, B2_LOAD),
    b3: at('b3', s3, B3_LOAD),
    dl: at('dl', Math.max(2, sets - 1), DL_LOAD),
  };
}
